static uint64_t now_ns(clockid_t id){struct timespec t; if(clock_gettime(id,&t)!=0)return 0;return (uint64_t)t.tv_sec*UINT64_C(1000000000)+(uint64_t)t.tv_nsec;}
static int64_t tv_us(struct timeval v){return (int64_t)v.tv_sec*INT64_C(1000000)+(int64_t)v.tv_usec;}
static int64_t self_cpu_us(void){struct rusage u;if(getrusage(RUSAGE_SELF,&u)!=0)return -1;return tv_us(u.ru_utime)+tv_us(u.ru_stime);}
