static int bsd(pid_t pid,struct proc_bsdinfo *b){memset(b,0,sizeof(*b));return proc_pidinfo(pid,PROC_PIDTBSDINFO,0,b,(int)sizeof(*b));}
static int same(struct identity id,struct proc_bsdinfo *b){return bsd(id.pid,b)==(int)sizeof(*b)&&b->pbi_pid==(uint32_t)id.pid&&b->pbi_start_tvsec==id.sec&&b->pbi_start_tvusec==id.usec;}
static int definitely_gone(struct identity id){struct proc_bsdinfo b;if(bsd(id.pid,&b)==(int)sizeof(b))return b.pbi_start_tvsec!=id.sec||b.pbi_start_tvusec!=id.usec;errno=0;int rc=kill(id.pid,0);return rc<0&&errno==ESRCH;}
