static void send_cmd(int fd,char command){write_all(fd,&command,1);}
static char command(int fd){char c=0;read_all(fd,&c,1);return c;}
static void send_msg(int fd,int code,pid_t other){struct rusage r;if(getrusage(RUSAGE_SELF,&r))fail("message-rusage");struct message m={code,getpid(),other,getppid(),tv_us(r.ru_utime),tv_us(r.ru_stime)};write_all(fd,&m,sizeof(m));}
