static struct child spawn_simple(const char *role,unsigned work){int c[2],m[2];if(pipe(c)||pipe(m))fail("pipe-simple");pid_t p=fork();if(p<0)fail("fork-simple");if(p==0){close(c[1]);close(m[0]);simple_body(c[0],m[1],role,work);}close(c[0]);close(m[1]);identify(p,role,1);struct child child={p,c[1],m[0]};return child;}
static void close_child(struct child c){close(c.cmd);close(c.msg);}
static void nested_body(int cmd,int msg){owned_n=0;alarm(15);identify(getpid(),"nested-child",0);burn(45);struct child g=spawn_simple("grandchild",75);message(g.msg,READY);send_msg(msg,READY,g.pid);if(command(cmd)!='Z')fail("nested-Z");send_cmd(g.cmd,'E');message(g.msg,EXITING);wait_zombie(g.pid,"grandchild");send_msg(msg,GRAND_ZOMBIE,g.pid);if(command(cmd)!='W')fail("nested-W");wait_usage(g.pid,"grandchild-waited-by-child");close_child(g);reference("nested-after-grandchild-wait");send_msg(msg,GRAND_WAITED,g.pid);if(command(cmd)!='E')fail("nested-E");reference("nested-child-before-exit");send_msg(msg,EXITING,g.pid);_exit(0);}
