static void daemon_body(int cmd,int msg){owned_n=0;alarm(12);identify(getpid(),"reparent-daemon",0);burn(30);send_msg(msg,READY,0);if(command(cmd)!='R')fail("daemon-R");send_msg(msg,REPORT,0);if(command(cmd)!='B')fail("daemon-B");burn(80);reference("daemon-after-reparent-work");send_msg(msg,WORKED,0);if(command(cmd)!='E')fail("daemon-E");reference("daemon-before-exit");send_msg(msg,EXITING,0);_exit(0);}
